-- Stores the blinded A15Q_C3 review packet (real freeze-approval dossier + decoy) and the answer key apart, and hands the packet to a SEPARATE GPT Native chat
-- as an operational event (HANDOFF_DEEP_CONTEXT). Data only: no action spec, checkpoint status or assertion changes. C3 stays PENDING.
-- The event carries only the reviewer prompt: no answer key, no producer chat, no producer verdict, no packet pointer.
-- Tier: OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT (not provider-attested, not independent review).
BEGIN;
CREATE FUNCTION pg_temp.a15_live(p_d jsonb, p_key jsonb) RETURNS text LANGUAGE plpgsql AS $lv$
DECLARE v_live jsonb; v_fp text; v_man text; v_c1 text; v_c2 text; v_ev jsonb;
BEGIN
 SELECT jsonb_agg(jsonb_build_object('unit',u.unit_code,'work_item_id',u.work_item_id,'c1',s.st[1],'c2',s.st[2],'c3',s.st[3],
     'c2_raw_sha256',u.unit_metadata#>>array['gpt_native_captures_v1',u.unit_code||'_C2','raw_output_sha256'],
     'c3_raw_sha256',u.unit_metadata#>>array['gpt_native_captures_v1',u.unit_code||'_C3','raw_output_sha256'],
     'c3_chat_sha256',u.unit_metadata#>>array['gpt_native_captures_v1',u.unit_code||'_C3','chat_transcript_sha256']) ORDER BY u.work_item_id),
   encode(sha256(convert_to(string_agg(u.unit_code||'|'||u.work_item_id||'|'||array_to_string(s.st,'|')||'|'||
     (u.unit_metadata#>>array['gpt_native_captures_v1',u.unit_code||'_C2','raw_output_sha256'])||'|'||
     (u.unit_metadata#>>array['gpt_native_captures_v1',u.unit_code||'_C3','raw_output_sha256'])||'|'||
     (u.unit_metadata#>>array['gpt_native_captures_v1',u.unit_code||'_C3','chat_transcript_sha256']), E'\n' ORDER BY u.work_item_id),'UTF8')),'hex')
  INTO v_live, v_fp
  FROM programacion.engineering_plan_units u
  CROSS JOIN LATERAL (SELECT array_agg(c.status ORDER BY c.sequence_no) st, count(*) n FROM programacion.engineering_work_checkpoints c WHERE c.work_item_id=u.work_item_id) s
  WHERE u.plan_code='PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1' AND u.unit_code ~ '^A([1-9]|1[0-4])Q$' AND s.n=3;
 IF v_live IS NULL OR jsonb_array_length(v_live)<>14 THEN RETURN 'LIVE_UNITS_COUNT'; END IF;
 IF v_live IS DISTINCT FROM p_d->'units' THEN RETURN 'LIVE_UNITS_NOT_DOSSIER'; END IF;
 IF EXISTS (SELECT 1 FROM jsonb_array_elements(v_live) e WHERE e->>'c1'<>'DONE' OR e->>'c2'<>'DONE' OR e->>'c3'<>'DONE') THEN RETURN 'LIVE_UNIT_NOT_DONE'; END IF;
 IF v_fp IS DISTINCT FROM p_d->>'units_fingerprint_sha256' OR v_fp IS DISTINCT FROM p_key->>'units_fingerprint_sha256' THEN RETURN 'LIVE_FINGERPRINT'; END IF;
 v_man := p_d#>>'{a15_c1,source_manifest_sha256}';
 IF v_man IS DISTINCT FROM p_d#>>'{a15_c2,a15_manifest_sha256}' OR v_man !~ '^[0-9a-f]{64}$' THEN RETURN 'MANIFEST_MISMATCH_IN_DOSSIER'; END IF;
 SELECT assertion_receipt->>'evidence_ref' INTO v_c1 FROM programacion.engineering_work_checkpoints WHERE work_item_id=1125 AND checkpoint_code='A15Q_C1' AND status='DONE';
 SELECT assertion_receipt->>'evidence_ref' INTO v_c2 FROM programacion.engineering_work_checkpoints WHERE work_item_id=1125 AND checkpoint_code='A15Q_C2' AND status='DONE';
 IF v_c1 IS NULL OR position(';sha256:'||v_man||';' in v_c1)=0 OR position((p_d#>>'{a15_c1,ci_run}')||';gitcommit:'||(p_d#>>'{a15_c1,ci_commit}')||';' in v_c1)=0 THEN RETURN 'C1_EVIDENCE_NOT_DOSSIER'; END IF;
 IF v_c2 IS NULL OR position('git_fingerprint_sha256:'||(p_d#>>'{a15_c2,git_fingerprint_sha256}')||';' in v_c2)=0
    OR position('a15_manifest_sha256:'||v_man||';' in v_c2)=0 OR position('pg01_contract_blob:'||(p_d#>>'{a15_c2,pg01_contract_blob}')||';' in v_c2)=0
    OR position('pg01_guard_md5:'||(p_d#>>'{a15_c2,pg01_guard_md5}')||';' in v_c2)=0 THEN RETURN 'C2_EVIDENCE_NOT_DOSSIER'; END IF;
 SELECT payload INTO v_ev FROM public.lf_eventos WHERE id=20994 AND evento_tipo='HANDOFF_DEEP_CONTEXT';
 IF v_ev IS NULL OR v_ev->>'packet_sha256' IS DISTINCT FROM p_d#>>'{a15_c1,refreeze_confirmation,packet_sha256}' THEN RETURN 'REFREEZE_EVENT_NOT_DOSSIER'; END IF;
 IF (p_d#>>'{guards,runtime_activation}')<>'false' OR (p_d#>>'{guards,production_activation}')<>'false' OR (p_d#>>'{guards,story_retirement_authorized}')<>'false'
    OR (p_d#>>'{tier,provider_attested}')<>'false' OR (p_d#>>'{tier,independent_review}')<>'false' OR (p_d#>>'{tier,real_execution_receipt}')<>'false' THEN RETURN 'GUARDS_NOT_FALSE'; END IF;
 RETURN 'OK';
END $lv$;
DO $a15q_c3_prep$
DECLARE
 v_plan constant text := 'PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1';
 v_unit constant text := 'A15Q';
 v_cp constant text := 'A15Q_C3';
 v_c2 constant text := 'A15Q_C2';
 v_wi constant bigint := 1125;
 v_exec constant text := 'ANALYSIS_QUAL_C3_GPT_HANDOFF_V1|A15Q_C3';
 v_packet_sha constant text := '72d3f12f20f6334f88ec78486f1ea900bbdce6fe2cfbeb70016c04874da2bef3';
 v_packet jsonb := $pkt${"checkpoint":"A15Q_C3","checks":[{"code":"ALL_14_UNITS_QUALIFIED","statement":"Las 14 unidades A1Q a A14Q aparecen, cada una con c1, c2 y c3 en DONE y con sus hashes c2_raw_sha256, c3_raw_sha256 y c3_chat_sha256 presentes (64 hex). Ninguna falta ni está pendiente."},{"code":"FREEZE_BINDING_EXACT","statement":"El hash del manifiesto de freeze es exactamente el mismo en a15_c1.source_manifest_sha256 y en a15_c2.a15_manifest_sha256; la confirmación del refreeze y la reconciliación Git-Supabase (drift_found 0) están ligadas a ese mismo freeze."},{"code":"NO_OVERCLAIM_NO_ACTIVATION","statement":"runtime_activation, production_activation y story_retirement_authorized son false; el nivel de evidencia declara provider_attested, independent_review y real_execution_receipt en false; el alcance de aprobación no afirma más que el freeze de análisis."}],"criterion":"Aprobación independiente de freeze: el expediente solo puede aprobarse si prueba, con sus propios datos, que las 14 unidades están calificadas, que el freeze está atado al mismo manifiesto en todos los puntos y que no se declara ninguna activación ni sobre-reclamo. No se infiere de que algo figure como DONE.","decision_doc":"docs/programming-agent/ANALYSIS_A15_C2_C3_OWNER_DECISION_V1.md","evidence_tier":"OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT","input":{"input_literal":"Solicitud: decidir si se aprueba el freeze (refreeze) del Análisis V1 del Agente de Programación (unidad A15). Se entrega un expediente de aprobación en JSON. Aprobar solo si el expediente, por sí mismo, cumple los tres chequeos; no asumir cumplimiento por el estado declarado."},"items":[{"item_id":"ITEM_A","text":"{\"a15_c1\":{\"ci_commit\":\"baa499fc25c0517cf26a70f9ef33574951e9b6f3\",\"ci_run\":\"github://cristhianlujan/claude-persona-lf-patch/actions/runs/38646492757\",\"refreeze_confirmation\":{\"chat\":\"https://chatgpt.com/g/g-p-6a6d99aa6330819180764b10e86c9392-agente-de-programacion/c/6acffd61-8450-83e8-b8af-74bb1429c1c8\",\"chat_sha256\":\"e4809a634f25431b2ec6a3afff2c119781d9d0bbd7c468a6cfad226447fcfc2c\",\"covers\":\"BUNDLE_INTEGRITY_AND_MANIFEST_CONSISTENCY_ONLY\",\"event\":\"lf_eventos://20994\",\"packet_sha256\":\"2bed03d21de741c9dfe8c15ed4bcb9197f5e4b5b4e5586cbc1f3807ace94baaf\",\"raw_sha256\":\"056903fdc73de48be9522ac078238d0a3436d64494f6b4b483725d62312b1960\",\"verdict\":\"CONFIRMED\"},\"source_manifest_sha256\":\"4ecb0fc2664bbfce80892d15d828d2344b45c09628b35b07f3db1597837d26c1\",\"status\":\"DONE\"},\"a15_c2\":{\"a15_manifest_sha256\":\"4ecb0fc2664bbfce80892d15d828d2344b45c09628b35b07f3db1597837d26c1\",\"drift_found\":0,\"git_fingerprint_sha256\":\"e082580ffdb447b8638d9a2d7f68cade1a113b0ced21f5a1ce779fcb6ae080bd\",\"method\":\"GIT_SUPABASE_RECONCILIATION_EXECUTED_IN_DB\",\"pg01_contract_blob\":\"56e561a72f8cfd9d085dd8087b854ff2ac740b1b\",\"pg01_guard_md5\":\"aa527bec9207b5cb275ec4a2e4e2bcdf\",\"status\":\"DONE\"},\"approval_scope\":\"Approves only the freeze of the Analysis V1 contracts as analysis artifacts; it does not activate runtime, does not activate production and does not retire any story.\",\"guards\":{\"production_activation\":false,\"runtime_activation\":false,\"story_retirement_authorized\":false},\"manifest_state\":\"ANALYSIS_V1_REFREEZE_CANDIDATE\",\"owner_decisions\":[{\"doc\":\"docs/programming-agent/ANALYSIS_C3_TIER_ACCEPTANCE_DECISION_V1.md\",\"scope\":\"C3_A1Q_TO_A14Q\",\"sha256\":\"902811e79f8e8a10e8687d4387c32ae116250bb4ce12d2171444a85bfcdd2909\"},{\"doc\":\"docs/programming-agent/ANALYSIS_A15_C2_C3_OWNER_DECISION_V1.md\",\"scope\":\"A15Q_C2_AND_A15Q_C3\",\"sha256\":\"c516d915c8caf5809723ae9335c7edfd184efa5a0ddc374a99ada4dacaa6d792\"}],\"plan\":\"PROGRAMMING_AGENT_ANALYSIS_REMEDIATION_V1\",\"schema\":\"ANALYSIS_A15_FREEZE_APPROVAL_DOSSIER_V1\",\"subject\":\"A15 refreeze of ANALYSIS_V1\",\"tier\":{\"evidence_tier\":\"OWNER_APPROVED_GPT_NATIVE_IN_CHAT_EQUIVALENT\",\"independent_review\":false,\"provider_attested\":false,\"real_execution_receipt\":f