 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_before_cps FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi FOR UPDATE;
 IF v_m IS NULL THEN RAISE EXCEPTION 'A15Q_UNIT_NOT_FOUND'; END IF;
 v_raw := (SELECT text FROM jsonb_to_recordset(v_packet->'items') AS i(item_id text, text text) WHERE item_id=v_key->>'real_item_id');
 IF v_raw IS NULL OR encode(sha256(convert_to(v_raw,'UTF8')),'hex') <> v_key->>'dossier_sha256' THEN RAISE EXCEPTION 'A15Q_C3_DOSSIER_SHA'; END IF;
 v_res := pg_temp.a15_live(v_raw::jsonb, v_key);
 IF v_res<>'OK' THEN RAISE EXCEPTION 'A15Q_C3_LIVE_EVIDENCE_CHECK:%', v_res; END IF;
 IF v_packet->'input'->>'input_literal' IS NULL THEN RAISE EXCEPTION 'A15Q_C3_INPUT_MISSING'; END IF;
 v_decoy := v_raw;
 FOR v_e IN SELECT * FROM jsonb_array_elements(v_key->'replacements') LOOP
  v_old := v_e->>0; v_new := v_e->>1;
  IF (length(v_raw)-length(replace(v_raw,v_old,'')))<>length(v_old) THEN RAISE EXCEPTION 'A15Q_C3_DECOY_REPLACEMENT_NOT_UNIQUE'; END IF;
  v_decoy := replace(v_decoy,v_old,v_new);
 END LOOP;
 IF v_decoy = v_raw OR encode(sha256(convert_to(v_decoy,'UTF8')),'hex') <> v_key->>'decoy_sha256' THEN RAISE EXCEPTION 'A15Q_C3_DECOY_MISMATCH'; END IF;
 PERFORM v_decoy::jsonb;
 IF (SELECT text FROM jsonb_to_recordset(v_packet->'items') AS i(item_id text, text text) WHERE item_id=v_key->>'real_item_id') IS DISTINCT FROM v_raw
    OR (SELECT text FROM jsonb_to_recordset(v_packet->'items') AS i(item_id text, text text) WHERE item_id=v_key->>'decoy_item_id') IS DISTINCT FROM v_decoy
    OR jsonb_array_length(v_packet->'items')<>2 THEN RAISE EXCEPTION 'A15Q_C3_ITEMS_NOT_FROM_DOSSIER'; END IF;
 IF position('DECOY' in v_packet::text)>0 OR position('REAL' in v_packet->>'prompt_for_gpt')>0
  THEN RAISE EXCEPTION 'A15Q_C3_PACKET_NOT_BLIND'; END IF;
 IF v_m#>'{gpt_native_packets_v1,A15Q_C3}' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A15Q_C3,packet_sha256}' <> v_packet_sha
    AND NOT (v_key->>'supersedes_packet_sha256' IS NOT NULL AND v_m#>>'{gpt_native_packets_v1,A15Q_C3,packet_sha256}' = v_key->>'supersedes_packet_sha256' AND v_m#>'{gpt_native_captures_v1,A15Q_C3}' IS NULL)
  THEN RAISE EXCEPTION 'A15Q_C3_PACKET_DIFFERENT_ALREADY_STORED'; END IF;
 v_before_specs := v_m->'action_specs_v1';
 UPDATE programacion.engineering_plan_units SET unit_metadata = v_m
   || jsonb_build_object('gpt_native_packets_v1', COALESCE(v_m->'gpt_native_packets_v1','{}'::jsonb) || jsonb_build_object('A15Q_C3',v_packet))
   || jsonb_build_object('gpt_native_c3_keys_v1', COALESCE(v_m->'gpt_native_c3_keys_v1','{}'::jsonb) || jsonb_build_object('A15Q_C3',v_key))
  WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 SELECT unit_metadata INTO v_m FROM programacion.engineering_plan_units WHERE plan_code=v_plan AND unit_code=v_unit AND work_item_id=v_wi;
 IF v_m#>'{gpt_native_packets_v1,A15Q_C3}' IS DISTINCT FROM v_packet OR v_m#>'{gpt_native_c3_keys_v1,A15Q_C3}' IS DISTINCT FROM v_key THEN RAISE EXCEPTION 'A15Q_C3_READBACK_MISMATCH'; END IF;
 IF v_m->'action_specs_v1' IS DISTINCT FROM v_before_specs THEN RAISE EXCEPTION 'A15Q_C3_SPECS_CHANGED'; END IF;
 IF NOT EXISTS (SELECT 1 FROM public.lf_eventos WHERE evento_tipo='HANDOFF_DEEP_CONTEXT' AND created_by_execution_id=v_exec) THEN
  INSERT INTO public.lf_eventos(evento_tipo,entidad_tipo,entidad_codigo,descripcion,severidad,origen,created_by_execution_id,payload)
  VALUES('HANDOFF_DEEP_CONTEXT','PROGRAM_PLAN',v_plan||'.A15Q_C3.GPT_NATIVE_HANDOFF',
   'Blinded A15Q_C3 review packet handed to a separate GPT Native chat; no acceptance declared.','INFO','DERIVE_FROM_EXECUTION_ID',v_exec,
   jsonb_build_object('evidence_schema_version','operational-event/v2','execution_id',v_exec,'producer','ANALYSIS_QUAL_C3_GPT_HANDOFF_V1',
    'purpose','Hand the blinded A15Q_C3 review packet to GPT Native in a chat separate from the A15 C1 refreeze-confirmation chat.',
    'occurred_at',to_char(clock_timestamp() AT TIME ZONE 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"+00:00"'),
    'acceptance_declared',false,'subject_ref',v_packet->>'subject_ref','checkpoint',v_cp,'work_item_id',v_wi,
    'packet_sha256',v_packet_sha,'producer_mode','GPT_NATIVE_REVIEW','evidence_tier',v_packet->>'evidence_tier','provider_attested',false,
    'separate_chat_required',true,'instructions_for_gpt',v_packet->>'prompt_for_gpt',
    'return_instructions','Reply in this NEW chat with ONLY the JSON object, unedited. Do not use the A15 C1 confirmation chat. Do not claim provider attestation.',
    'limits_note','Owner-approved GPT Native in-chat equivalent for C3. Not a provider receipt and not an independent review. The checkpoint stays pending until a captured review is verified.'))
  RETURNING id INTO v_id;
  SELECT payload INTO v_p FROM public.lf_eventos WHERE id=v_id;
  IF v_p->>'packet_sha256' IS DISTINCT FROM v_packet_sha OR v_p->>'instructions_for_gpt' IS DISTINCT FROM v_packet->>'prompt_for_gpt' THEN RAISE EXCEPTION 'A15Q_C3_HANDOFF_READBACK_MISMATCH'; END IF;
 END IF;
 SELECT string_agg(checkpoint_code||':'||status,',' ORDER BY sequence_no) INTO v_after_cps FROM programacion.engineering_work_checkpoints WHERE work_item_id=v_wi;
 IF v_after_cps IS DISTINCT FROM v_before_cps THEN RAISE EXCEPTION 'A15Q_C3_CHECKPOINTS_CHANGED'; END IF;
END
$a15q_c3_prep$;
COMMIT;
